# mark 8 cells interior to maximal alternating sequence length >=5 along row/col
out=[r[:] for r in g]
R,C=len(g),len(g[0])
for axis in [0,1]:
 for i in range(R):
  j=0
  lim=C if axis==1 else R
  while j<lim:
   # line coordinate (i,j) row for axis1 or col for axis0
   def val(k): return g[i][k] if axis==1 else g[k][i]
   if val(j)==8: j+=1; continue
   start=j; j+=1
   while j<lim and val(j)!=val(j-1): j+=1
   # segment non-background alternating, length >= 5; recolor interior background cells
   if j-start>=5:
    for k in range(start+1,j-1):
     if val(k)==8:
      if axis==1: out[i][k]=2
      else: out[k][i]=2
print(out)

